"""Operator browser page; credentials stay in the browser session."""

PAGE = b"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event Automation</title><style>body{font:16px system-ui;max-width:760px;margin:3rem auto;padding:1rem;background:#f7f9fc;color:#172033}main{background:white;padding:2rem;border-radius:14px}input,textarea,select,button{font:inherit;display:block;width:100%;box-sizing:border-box;padding:.6rem;margin:.5rem 0 1rem}textarea{min-height:7rem}button{background:#175cd3;color:white;border:0;border-radius:8px;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef3fa;padding:1rem}</style></head><body><main><h1>Event Automation</h1><label>Admin token<input id="token" type="password"></label><label>Event ID<input id="event-id"></label><label>Workflow<select id="workflow"><option>log</option><option>forward</option></select></label><label>JSON payload<textarea id="payload">{}</textarea></label><button id="submit">Submit event</button><button id="job">Inspect event</button><button id="metrics">Queue metrics</button><button id="requeue">Requeue dead event</button><pre id="result" aria-live="polite"></pre></main><script>const token=document.getElementById('token'),id=document.getElementById('event-id'),result=document.getElementById('result');async function call(path,body){try{const response=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Admin-Token':token.value},body:body?JSON.stringify(body):undefined});result.textContent=JSON.stringify(await response.json(),null,2)}catch(error){result.textContent=String(error)}}document.getElementById('submit').onclick=()=>{try{call('/ui/submit',{event_id:id.value,workflow:document.getElementById('workflow').value,payload:JSON.parse(document.getElementById('payload').value)})}catch(error){result.textContent=String(error)}};document.getElementById('job').onclick=()=>call('/jobs/'+encodeURIComponent(id.value));document.getElementById('metrics').onclick=()=>call('/metrics');document.getElementById('requeue').onclick=()=>call('/dead/requeue',{event_id:id.value});</script></body></html>"""
